        this.id = id;
        this.bookId = bookId;
        this.memberId = memberId;
        this.fulfilled = fulfilled;
    }

    public UUID getId() {
        return id;
    }

    public UUID getBookId() {
        return bookId;
    }

    public UUID getMemberId() {
        return memberId;
    }

    public boolean isFulfilled() {
        return fulfilled;
